{
  "findings": [
    {
      "check_id": "CKV_GCP_11",
      "title": "Ensure that Cloud SQL database Instances are not open to the world",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "The authorized_networks block includes '0.0.0.0/0', which allows access from any IP address on the internet, exposing the database to unauthorized access attempts."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "Ensure all Cloud SQL database instance requires all incoming connections to use SSL",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The require_ssl flag is set to false, allowing unencrypted connections to the database, which risks data interception and man-in-the-middle attacks."
    },
    {
      "check_id": "CKV_GCP_51",
      "title": "Ensure PostgreSQL database 'log_checkpoints' flag is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "LOW",
      "explanation": "The log_checkpoints flag is not explicitly enabled in database_flags, missing audit trail information regarding checkpoint events."
    },
    {
      "check_id": "CKV_GCP_52",
      "title": "Ensure PostgreSQL database 'log_connections' flag is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "LOW",
      "explanation": "The log_connections flag is not explicitly enabled in database_flags, missing audit trail information regarding new connection attempts."
    },
    {
      "check_id": "CKV_GCP_53",
      "title": "Ensure PostgreSQL database 'log_disconnections' flag is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "LOW",
      "explanation": "The log_disconnections flag is not explicitly enabled in database_flags, missing audit trail information regarding connection terminations."
    },
    {
      "check_id": "CKV_GCP_54",
      "title": "Ensure PostgreSQL database 'log_lock_waits' flag is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "LOW",
      "explanation": "The log_lock_waits flag is not explicitly enabled in database_flags, missing audit trail information regarding lock contention issues."
    },
    {
      "check_id": "CKV2_GCP_13",
      "title": "Ensure PostgreSQL database flag 'log_duration' is set to 'on'",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "LOW",
      "explanation": "The log_duration flag is not explicitly enabled in database_flags, missing performance and audit data regarding query execution times."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"operational_database\" {\n  name             = \"autonomous-drone-delivery-management-platform-sql-operational\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  settings {\n    tier = var.database_tier\n    ip_configuration {\n      ipv4_enabled = true\n      authorized_networks {\n        value = \"10.0.0.0/16\"\n        name  = \"internal-network\"\n      }\n      require_ssl = true\n    }\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n    database_flags {\n      name  = \"log_statement\"\n      value = \"all\"\n    }\n    database_flags {\n      name  = \"log_checkpoints\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_connections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_disconnections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_duration\"\n      value = \"on\"\n    }\n  }\n  deletion_protection = false\n}",
  "fix_summary": "Removed the public '0.0.0.0/0' authorized network entry to restrict access to internal networks only. Enabled SSL requirement for all connections. Added explicit database flags for log_checkpoints, log_connections, log_disconnections, log_lock_waits, and log_duration to ensure comprehensive audit logging."
}
